/**
 * "Who ruled this city?" — the states and peoples that held each city in
 * src/data/cities.json, as drawn in every map snapshot.
 *
 * cityRulers.json is generated by scripts/build-city-rulers.mjs (it searches
 * all the snapshots, which is too slow to do per request). Re-run that script
 * after editing cities.json.
 */
import CITIES from "@/data/cities.json";
import RULERS from "@/data/cityRulers.json";
import { resolveFeature } from "@/data/crosswalk";

export interface City {
  slug: string;
  name: string;
  country: string;
  lat: number;
  lng: number;
  /** Earlier names, comma-separated ("Byzantium, Constantinople"). */
  formerly?: string;
}

/** One stretch of snapshots in which the map draws the same ruler. */
export interface RulerSpan {
  /** First snapshot year that draws this ruler. */
  from: number;
  /** First later snapshot year that draws someone else; null if it still holds. */
  to: number | null;
  /** Territory name in the snapshot; null when the map draws no state here. */
  name: string | null;
  /** The power that territory answered to, when the map records a different one. */
  sovereign: string | null;
  /** Atlas page for the ruler, when we have one. */
  href?: string;
}

export const CITY_LIST: readonly City[] = [...(CITIES as City[])].sort((a, b) => a.name.localeCompare(b.name));

export function getCity(slug: string): City | undefined {
  return CITY_LIST.find((c) => c.slug === slug);
}

/**
 * A city's rulers, oldest first. Leading empty stretches (before anyone is
 * drawn there) are dropped; later gaps are kept, since "no state on the map"
 * is itself part of the story.
 */
export function rulersOf(slug: string): RulerSpan[] {
  const spans = ((RULERS as Record<string, RulerSpan[]>)[slug] ?? []).map((s) => {
    const entry = s.name ? resolveFeature(s.name, s.sovereign ?? s.name, s.from) : undefined;
    return { ...s, href: entry ? `/place/${entry.slug}` : undefined };
  });
  const first = spans.findIndex((s) => s.name);
  return first === -1 ? [] : spans.slice(first);
}

/** Distinct ruler names, in order of first appearance. */
export function distinctRulers(spans: RulerSpan[]): string[] {
  return [...new Set(spans.flatMap((s) => (s.name ? [s.name] : [])))];
}

/** Great-circle distance in km, for "nearby cities". */
function distanceKm(a: City, b: City): number {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLng = (b.lng - a.lng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
}

export function nearbyCities(city: City, count = 6): City[] {
  return CITY_LIST.filter((c) => c.slug !== city.slug)
    .map((c) => ({ c, d: distanceKm(city, c) }))
    .sort((x, y) => x.d - y.d)
    .slice(0, count)
    .map((x) => x.c);
}
